export function ebible_licence_words_unread() {
  "What is said in place of the name of a licence when the terms a translation is offered on were not recognised.";
  "IT IS SPELLED HERE BECAUSE TWO SIDES HAVE TO AGREE ABOUT IT. One writes it, and a gate over the generated files has to be able to tell this answer apart from a real licence name - a file crediting somebody's scripture and naming no terms at all is exactly the failure that gate exists for, and it looks like an ordinary filled-in line from every angle except this word.";
  "IT SAYS THE READING FAILED RATHER THAN GUESSING, which errs in the same direction the reading of it does.";
  let words = "Terms not read";
  return words;
}
